import logo from "./logo.svg";
import Button from "react-bootstrap/Button";
import Row from "react-bootstrap/Row";
import Col from "react-bootstrap/Col";
import Container from "react-bootstrap/Container";

import { ReactComponent as ArrowUp } from './arrow-up.svg';
import { ReactComponent as ArrowDown } from './arrow-down.svg';
import { ReactComponent as ArrowLeft } from './arrow-left.svg';
import { ReactComponent as ArrowRight } from './arrow-right.svg';
import { ReactComponent as CloseBtn } from './close.svg';

import styles from './App.css';

//import { LineChart, XAxis, Tooltip, CartesianGrid, Line, YAxis, Legend } from "recharts";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { useState, useRef, useEffect } from "react";

const axios = require("axios").default;

const ip = process.env.REACT_APP_ROBOT_URL || "http://AstroVianu.local:8080";

function App() {

    //hover state bc why not bro ...

    useEffect(() => {
        document.body.style.margin = '0';
        document.body.style.padding = '0';
        document.body.style.position = 'relative';
        document.body.style.height = '100vh';
    }, []);

    const [isHover, setIsHover] = useState(false);

    const handleMouseEnter = () => {
        setIsHover(true);
    };

    const handleMouseLeave = () => {
        setIsHover(false);
    };

    const html = {

        backgroundColor: 'red',
        position: 'relative',
        margin: '0',
        padding: '0',
        height: '100vh'

    }

    const controller = {

        position: 'fixed',
        bottom: '0',
        //right: '0',
        left: '0',
        paddingBottom: '10px',
        zIndex: '1000'

    }

    const controller2 = {

        position: 'fixed',
        bottom: '0',
        //right: 'right',
        right: '0',
        paddingBottom: '10px',
        zIndex: '1000'

    }

    const btnConsole = {

        //color: 'white',
        backgroundColor: 'white',
        transition: 'all .5s',
        opacity: isHover ? '1' : '0.5',
        borderRadius: '50%',
        borderColor: 'white',
        // padding: '1px 20px',
        //heigth: '50px',
        //width: '50px',
        padding: '0px',
        marginRigth: 'auto',
        marginLeft: 'auto'

    }

    const svgsize = {
        // width: '60px',
        // heigth: '60px',
        margin: '0px auto'
    }

    let cnt = 0;

    const [data, setData] = useState([]);
    const [add, setAdd] = useState(0);
    const [unghi, setUnghi] = useState(0);

    const [dataTemp, setDataTemp] = useState([]);
    const [dataPres, setDataPres] = useState([]);
    const [dataHum, setDataHum] = useState([]);

    const [dataInv, setDataInv] = useState([]);

    const [dataHabIndex, setHabIndex] = useState([]);

    const randNum = () => {

        return Math.round(Math.random() * 1000 + 1);

    }

    // function dataParasite() {

    //     dataInv.push({
    //         name: ${add},
    //         "CH4": randNum(),
    //         "H2": randNum(),
    //         "NH3": randNum(),
    //         "Temperature": randNum(),
    //         "Pressure": randNum(),
    //         "Humidity": randNum()
    //     })

    //     console.log(dataInv)

    //     setDataInv(dataInv);

    //     setAdd(add => add + 1);

    // }

    const actionTimerRef = useRef(null);

    const startContinuousAction = (actionFunction) => {
        // Prevent stacking: If a timer is already running, don't start a new one
        if (actionTimerRef.current !== null) return;

        // Execute immediately on the initial press
        actionFunction(); 

        // Set the loop and save its ID directly inside the ref container
        actionTimerRef.current = setInterval(() => {
            actionFunction();
        }, 50); // 150ms provides a stable request window over local network
    };

    const stopContinuousAction = () => {
        // If an active loop exists in our ref container, clear it completely
        if (actionTimerRef.current !== null) {
            clearInterval(actionTimerRef.current);
            actionTimerRef.current = null;
        }
    };

    function addResponseToData(response) {

        let response_obj;
        try {
            response_obj = typeof response === "string" ? JSON.parse(response) : response;
        } catch (e) {
            response_obj = response;
        }

        const response_string = response_obj.data || "";
        const words = response_string.split(/\s+/);

        let response_map = {};
        const regex = /(\w+)\s*=\s*([0-9.]+)/g;
        let match;
        while ((match = regex.exec(response_string)) !== null) {
            // match[1] is the key (e.g., 'temperature'), match[2] is the value (e.g., '33.38157')
            response_map[match[1].toLowerCase()] = match[2];
        }

        console.log("Parsed Metrics Map:", response_map);

        // Read the values safely, providing fallback values if they don't exist
        let T = response_map['temperature'] ? (parseFloat(response_map['temperature']) - 4) : 0;
        let P = response_map['pressure'] ? parseFloat(response_map['pressure']) : 0;
        let U = response_map['humidity'] ? parseFloat(response_map['humidity']) : 0;
        let CH4 = response_map['mq4'] ? parseFloat(response_map['mq4']) : 0;
        let H2 = response_map['mq8'] ? parseFloat(response_map['mq8']) : 0;
        let NH3 = response_map['mq135'] ? parseFloat(response_map['mq135']) : 0;
        let M = response_map['miuoni'] ? parseFloat(response_map['miuoni']) : 1;

        function get_parameter_index(val, val_optim, deviation_less_equal, deviation_greater)
        {
            let score;
            if (val <= val_optim)
            {
                // folosim deviation_less_equal
                score = Math.exp(-Math.pow((val - val_optim) / deviation_less_equal, 2));
            }
            else
            {
                // folosim deviation_greater
                score = Math.exp(-Math.pow((val - val_optim) / deviation_greater, 2));
            }

            return score;
        }

        function get_habitability_index()
        {
            let I_T = get_parameter_index(T, 22, 30, 15);
            let I_P = get_parameter_index(P, 1013.25, 200, 800);
            let I_U = get_parameter_index(U, 45, 20, 45);
            let I_CH4 = get_parameter_index(CH4, 329, 250, 250);
            let I_H2 = get_parameter_index(H2, 366, 225, 225);
            let I_NH3 = get_parameter_index(NH3, 300, 350, 350);
            let I_M = get_parameter_index(M, 1, 100, 5);

            let W_T = 0.25;
            let W_P = 0.20;
            let W_U = 0.20;
            let W_CH4 = 0.07;
            let W_H2 = 0.08;
            let W_NH3 = 0.08;
            let W_M = 0.12;

            let habitability_index = Math.pow(I_T, W_T) * Math.pow(I_P, W_P) * Math.pow(I_U, W_U) *
                                     Math.pow(I_CH4, W_CH4) * Math.pow(I_H2, W_H2) * Math.pow(I_NH3, W_NH3) *
                                     Math.pow(I_M, W_M);

            return habitability_index;
        }

        setData(prevData => {
            const nextIndex = prevData.length; // Always unique and sequential
            return [
                ...prevData,
                { 
                    name: `${nextIndex}`, 
                    "CH4": CH4, 
                    "H2": H2, 
                    "NH3": NH3 
                }
            ];
        });

        setHabIndex(prevHabIndex => [
            ...prevHabIndex, 
            { name: `${prevHabIndex.length}`, 'Habitability Index': get_habitability_index() }
        ]);

        setDataTemp(prevTemp => [
            ...prevTemp,
            { name: `${prevTemp.length}`, "Temperature": T }
        ]);

        setDataPres(prevPres => [
            ...prevPres,
            { name: `${prevPres.length}`, "Pressure": P }
        ]);

        setDataHum(prevHum => [
            ...prevHum,
            { name: `${prevHum.length}`, "Humidity": U }
        ]);

        setAdd(add => add + 1);
    }

    function handleFront() {
        console.log("OP")
        axios.get(ip + "/move/fata").then(function (response) {
            console.log(response);
            addResponseToData(JSON.stringify(response));
        });

        //dataParasite();
    }

    function handleBack() {
        axios.get(ip + "/move/spate").then(function (response) {
            console.log(response);
            addResponseToData(JSON.stringify(response));
        });
    }

    function handleLeft() {
        axios.get(ip + "/move/stanga").then(function (response) {
            console.log(response);
            addResponseToData(JSON.stringify(response));
        });
        setUnghi(prev => prev >= -1 ? prev - 1 : prev);
    }
    function handleRight() {
        axios.get(ip + "/move/dreapta").then(function (response) {
            console.log(response);
            addResponseToData(JSON.stringify(response));
        });
        setUnghi(prev => prev <= 1 ? prev + 1 : prev);
    }
    function handleOpen() {
        // console.log(data);
        axios.get(ip + "/gheara/open").then(function (response) {
            console.log(response);
            addResponseToData(JSON.stringify(response));
        });
    }
    function handleClose() {
        axios.get(ip + "/gheara/close").then(function (response) {
            console.log(response);
            addResponseToData(JSON.stringify(response));
        });
    }
    return (
        <Container className="m-0">



            {/* //<title>My Leaflet Routing Machine Example</title> */}
            < link rel="stylesheet" href="http://cdn.leafletjs.com/leaflet-0.7.3/leaflet.css" />
            <link rel="stylesheet" href="LeafletRoutingMachine/dist/leaflet-routing-machine.css" />
            <link rel="stylesheet" href="http://netdna.bootstrapcdn.com/font-awesome/4.0.3/css/font-awesome.css" />
            <link rel="stylesheet" href="css/easy-button.css" />



            {/* <Row> */}

            <Container style={controller} className="w-25">
                <Row>
                    <Col xs={12} className="p-0" align='center'>
                        {/* Forward Button */}
                        <Button 
                            style={btnConsole} 
                            onMouseEnter={handleMouseEnter}
                            onMouseLeave={() => { handleMouseLeave(); stopContinuousAction(); }}
                            onMouseDown={() => startContinuousAction(handleFront)}
                            onMouseUp={stopContinuousAction}
                            onTouchStart={(e) => { e.preventDefault(); startContinuousAction(handleFront); }}
                            onTouchEnd={stopContinuousAction}
                        >
                            <ArrowUp style={svgsize} />
                        </Button>
                    </Col>
                </Row>
                <Row>
                    <Col xs={6} className="p-0" align='center'>
                        {/* Left Button */}
                        <Button 
                            style={btnConsole} 
                            className="btn-warning" 
                            onMouseEnter={handleMouseEnter}
                            onMouseLeave={() => { handleMouseLeave(); stopContinuousAction(); }}
                            onMouseDown={() => startContinuousAction(handleLeft)}
                            onMouseUp={stopContinuousAction}
                            onTouchStart={(e) => { e.preventDefault(); startContinuousAction(handleLeft); }}
                            onTouchEnd={stopContinuousAction}
                        >
                            <ArrowLeft style={svgsize} />
                        </Button>
                    </Col>

                    <Col xs={6} className="p-0" align='center'>
                        {/* Right Button */}
                        <Button 
                            style={btnConsole} 
                            className="btn-warning" 
                            onMouseEnter={handleMouseEnter}
                            onMouseLeave={() => { handleMouseLeave(); stopContinuousAction(); }}
                            onMouseDown={() => startContinuousAction(handleRight)}
                            onMouseUp={stopContinuousAction}
                            onTouchStart={(e) => { e.preventDefault(); startContinuousAction(handleRight); }}
                            onTouchEnd={stopContinuousAction}
                        >
                            <ArrowRight style={svgsize} />
                        </Button>
                    </Col>
                </Row>
                <Row>
                    <Col xs={12} className="p-0" align='center'>
                        {/* Backward Button */}
                        <Button 
                            style={btnConsole} 
                            onMouseEnter={handleMouseEnter}
                            onMouseLeave={() => { handleMouseLeave(); stopContinuousAction(); }}
                            onMouseDown={() => startContinuousAction(handleBack)}
                            onMouseUp={stopContinuousAction}
                            onTouchStart={(e) => { e.preventDefault(); startContinuousAction(handleBack); }}
                            onTouchEnd={stopContinuousAction}
                        >
                            <ArrowDown style={svgsize} />
                        </Button>
                    </Col>
                </Row>
            </Container>

            <Container className="w-25" style={controller2}>
                <Row>

                    <Col xs={6} className="p-0 mt-5" align="left">
                        <Button style={btnConsole} onClick={handleOpen} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <CloseBtn style={svgsize} />
                        </Button>
                    </Col>
                </Row>
                <Row>
                    <Col xs={6} className="p-0 mt-5" align="left">
                        <Button style={btnConsole} onClick={handleClose} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <CloseBtn style={svgsize} />
                        </Button>
                    </Col>
                </Row>
            </Container>

            {/*<Container style={controller} className="w-25">
                <Row>
                    <Col xs={12} className="p-0" align='center'>
                        <Button style={btnConsole} onClick={handleFront} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <ArrowUp style={svgsize} />
                        </Button>
                    </Col>
                </Row>
                <Row>
                    <Col xs={6} className="p-0" align='center'>
                        <Button style={btnConsole} onClick={handleLeft} className="btn-warning" onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <ArrowLeft style={svgsize} />
                        </Button>
                    </Col>

                    <Col xs={6} className="p-0" align='center'>
                        <Button style={btnConsole} className="btn-warning" onClick={handleRight} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <ArrowRight style={svgsize} />
                        </Button>
                    </Col>
                </Row>
                <Row>
                    <Col xs={12} className="p-0" align='center'>
                        <Button style={btnConsole} onClick={handleBack} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <ArrowDown style={svgsize} />
                        </Button>
                    </Col>
                </Row>
            </Container>

            <Container className="w-25" style={controller2}>
                <Row>

                    <Col xs={6} className="p-0 mt-5" align="left">
                        <Button style={btnConsole} onClick={handleOpen} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <CloseBtn style={svgsize} />
                        </Button>
                    </Col>
                </Row>
                <Row>
                    <Col xs={6} className="p-0 mt-5" align="left">
                        <Button style={btnConsole} onClick={handleClose} onMouseEnter={handleMouseEnter}
                            onMouseLeave={handleMouseLeave}>
                            <CloseBtn style={svgsize} />
                        </Button>
                    </Col>
                </Row>
            </Container>*/}

            {/* // <ResponsiveContainer width="100%" height="100%"> */}
            <div style={{ width: '100%', height: 500 }}>
                <ResponsiveContainer>
                    <LineChart
                        className="mt-5"
                        width={500}
                        height={500}
                        data={data}
                        margin={{
                            top: 5,
                            right: 30,
                            left: 20,
                            bottom: 5,
                        }}

                    >

                        <CartesianGrid className="da" strokeDasharray="3 3" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="CH4" stroke="#8884d8" fill="#8884d8" />
                        <Line type="monotone" dataKey="H2" stroke="#82ca9d" fill="#8884d8" />
                        <Line type="monotone" dataKey="NH3" stroke="#ff0000" fill="#8884d8" />
                    </LineChart>
                </ResponsiveContainer>

                {/* //</ResponsiveContainer> */}

            </div>

            <div style={{ width: '100%', height: 500 }}>
                <ResponsiveContainer>
                    <LineChart
                        className="mt-5"
                        width={500}
                        height={500}
                        data={dataHabIndex}
                        margin={{
                            top: 5,
                            right: 30,
                            left: 20,
                            bottom: 5,
                        }}

                    >

                        <CartesianGrid className="da" strokeDasharray="3 3" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="Habitability Index" stroke="#08a000" fill="#08a000" />
                    </LineChart>
                </ResponsiveContainer>

                {/* //</ResponsiveContainer> */}

            </div>

            <div style={{ width: '100%', height: 500 }}>
                <ResponsiveContainer>
                    <LineChart
                        className="mt-5"
                        width={500}
                        height={500}
                        data={dataTemp}
                        margin={{
                            top: 5,
                            right: 30,
                            left: 20,
                            bottom: 5,
                        }}

                    >

                        <CartesianGrid className="da" strokeDasharray="3 3" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="Temperature" stroke="#8884d8" fill="#8884d8" />

                    </LineChart>
                </ResponsiveContainer>

                {/* //</ResponsiveContainer> */}

            </div>

            <div style={{ width: '100%', height: 500 }}>
                <ResponsiveContainer>
                    <LineChart
                        className="mt-5"
                        width={500}
                        height={500}
                        data={dataPres}
                        margin={{
                            top: 5,
                            right: 30,
                            left: 20,
                            bottom: 5,
                        }}

                    >

                        <CartesianGrid className="da" strokeDasharray="3 3" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="Pressure" stroke="#8884d8" fill="#8884d8" />

                    </LineChart>
                </ResponsiveContainer>

                {/* //</ResponsiveContainer> */}

            </div>

            <div style={{ width: '100%', height: 500 }}>
                <ResponsiveContainer>
                    <LineChart
                        className="mt-5"
                        width={500}
                        height={500}
                        data={dataHum}
                        margin={{
                            top: 5,
                            right: 30,
                            left: 20,
                            bottom: 5,
                        }}

                    >

                        <CartesianGrid className="da" strokeDasharray="3 3" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="Humidity" stroke="#8884d8" fill="#8884d8" />

                    </LineChart>
                </ResponsiveContainer>

                {/* //</ResponsiveContainer> */}

            </div>

        </Container >

    );
}

export default App;
